/*
 * A293358  Solution of the complementary equation a(n) = a(n-1) + a(n-2) +
 *          b(n-1), where a(0) = 1, a(1) = 3, b(0) = 2, b(1) = 4.
 * https://oeis.org/A293358
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = a(n-1) + a(n-2) + b(n-1), a(0)=1, a(1)=3, b(0)=2, b(1)=4.
 *            The sequence a() and its complement b() are generated by
 *            iterating a(n) and taking b(n) as the smallest positive integer
 *            not yet used by either sequence
 * Range:     u8 n <= 7, u16 n <= 19, u32 n <= 35, u64 n <= 35, u128 n <= 35,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

seq_t a(idx_t n) {
    /* Cached values of a and b */
    static seq_t *a_cache = NULL;
    static seq_t *b_cache = NULL;
    static size_t a_len = 0, b_len = 0;
    static size_t a_cap = 0, b_cap = 0;

    /* Small‑number bookkeeping: numbers that have already appeared
       in either a or b, up to a fixed bound that is more than
       enough for n <= 10000. */
    static unsigned char *used = NULL;
    static size_t used_cap = 0;
    static idx_t next_unused = 0;

    /* Bound for used array – larger than any b(n) required for n <= 10000. */
    const idx_t USED_BOUND = 50000;   /* safe for the stated limits */

    /* Initialise on first call. */
    if (!a_cache) {
        a_cap = 64;
        a_cache = (seq_t *)malloc(a_cap * sizeof(seq_t));
        a_cache[0] = (seq_t)1;
        a_cache[1] = (seq_t)3;
        a_len = 2;

        b_cap = 64;
        b_cache = (seq_t *)malloc(b_cap * sizeof(seq_t));
        b_cache[0] = (seq_t)2;
        b_cache[1] = (seq_t)4;
        b_len = 2;

        used_cap = USED_BOUND;
        used = (unsigned char *)calloc(used_cap, 1);

        /* Mark the initial numbers as used. */
        used[1] = 1;  /* a(0) */
        used[2] = 1;  /* b(0) */
        used[3] = 1;  /* a(1) */
        used[4] = 1;  /* b(1) */

        next_unused = 5;
    }

    /* Return already computed value. */
    if (n < a_len)
        return a_cache[n];

    /* Compute terms up to n. */
    for (idx_t i = a_len; i <= n; ++i) {
        /* Ensure enough space. */
        if (a_len >= a_cap) {
            a_cap <<= 1;
            a_cache = (seq_t *)realloc(a_cache, a_cap * sizeof(seq_t));
        }
        if (b_len >= b_cap) {
            b_cap <<= 1;
            b_cache = (seq_t *)realloc(b_cache, b_cap * sizeof(seq_t));
        }

        /* Find the next b(i-1) as the smallest unused positive integer. */
        while (next_unused < (idx_t)used_cap && used[next_unused])
            ++next_unused;
        seq_t next_b = (seq_t)next_unused;

        /* Compute a(i). */
        seq_t next_a = a_cache[i - 1] + a_cache[i - 2] + b_cache[i - 1];

        /* Store computed values. */
        a_cache[a_len++] = next_a;
        b_cache[b_len++] = next_b;

        /* Mark the new numbers as used, if they lie within the bound. */
        if (next_a < (seq_t)used_cap)
            used[(size_t)next_a] = 1;
        if (next_b < (seq_t)used_cap)
            used[(size_t)next_b] = 1;
    }

    return a_cache[n];
}
